import { setElementInnerHtml, sanitizeHtml } from 'safevalues/dom';

interface Note {
  id: number;
  title: string;
  body: string;
  avatar: string;
  createdAt: string;
}

const STORAGE_KEY = 'porto-notes';
const FIXTURES_URL = '/fixtures.json';

let notes: Note[] = [];
let nextId = 1;
let selectedNoteId: number | null = null;
let searchQuery = '';

// Validate avatar URL scheme (http, https, data:image/)
function isValidAvatarUrl(url: string): boolean {
  if (!url) return true;
  try {
    if (url.startsWith('data:image/')) return true;
    const parsed = new URL(url);
    return parsed.protocol === 'http:' || parsed.protocol === 'https:';
  } catch {
    return false;
  }
}

// Load notes from localStorage or fixtures
async function initializeNotes() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    try {
      notes = JSON.parse(stored);
      nextId = Math.max(...notes.map(n => n.id), 0) + 1;
    } catch {
      notes = [];
      nextId = 1;
      await loadFixtures();
    }
  } else {
    await loadFixtures();
  }
}

async function loadFixtures() {
  try {
    const response = await fetch(FIXTURES_URL);
    const fixtures: Note[] = await response.json();
    notes = fixtures;
    nextId = Math.max(...notes.map(n => n.id), 0) + 1;
    saveNotes();
  } catch {
    notes = [];
    nextId = 1;
  }
}

function saveNotes() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
}

// Parse URL fragment: #q=query&note=id
function parseFragment() {
  const hash = location.hash.slice(1);
  const params = new URLSearchParams(hash);
  searchQuery = params.get('q') || '';
  selectedNoteId = params.has('note') ? parseInt(params.get('note')!) : null;
}

// Update URL fragment based on current state
function updateFragment() {
  const params = new URLSearchParams();
  if (searchQuery) params.set('q', searchQuery);
  if (selectedNoteId !== null) params.set('note', selectedNoteId.toString());
  const newHash = params.toString() ? '#' + params.toString() : '';
  history.replaceState(null, '', newHash);
}

// Filter notes based on search query
function getFilteredNotes(): Note[] {
  if (!searchQuery) return notes;
  const q = searchQuery.toLowerCase();
  return notes.filter(
    note => note.title.toLowerCase().includes(q) || note.body.toLowerCase().includes(q)
  );
}

// Render the feed
function renderFeed() {
  const feed = document.getElementById('feed')!;
  feed.innerHTML = '';

  const filtered = getFilteredNotes();
  const sortedNotes = [...filtered].reverse();

  for (const note of sortedNotes) {
    const article = document.createElement('article');
    article.className = 'note';
    article.setAttribute('data-note-id', note.id.toString());
    if (selectedNoteId === note.id) {
      article.setAttribute('aria-current', 'true');
    }

    const titleEl = document.createElement('h3');
    titleEl.className = 'note-title';
    titleEl.textContent = note.title;
    titleEl.style.cursor = 'pointer';
    titleEl.addEventListener('click', () => selectNote(note.id));

    const bodyEl = document.createElement('div');
    bodyEl.className = 'note-body';
    // Convert the text body with tags into HTML
    const bodyHtml = parseRichText(note.body);
    setElementInnerHtml(bodyEl, sanitizeHtml(bodyHtml));

    article.appendChild(titleEl);

    if (note.avatar && isValidAvatarUrl(note.avatar)) {
      const img = document.createElement('img');
      img.className = 'note-avatar';
      img.src = note.avatar;
      img.alt = 'Avatar';
      article.appendChild(img);
    }

    article.appendChild(bodyEl);
    feed.appendChild(article);
  }
}

// Parse rich text: convert <b>, <i>, <a>, <br> tags and newlines to HTML
function parseRichText(text: string): string {
  // Escape HTML special chars, but preserve our tags
  let html = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  // Restore allowed tags and convert them to actual HTML
  html = html.replace(/&lt;(b|strong|i|em|br|a href="[^"]*")&gt;/g, (match, tag) => {
    if (tag === 'b' || tag === 'strong') return '<b>';
    if (tag === 'i' || tag === 'em') return '<i>';
    if (tag === 'br') return '<br>';
    if (tag.startsWith('a href=')) {
      const href = tag.match(/href="([^"]*)"/)?.[1] || '';
      return `<a href="${escapeHtml(href)}">`;
    }
    return match;
  });

  html = html.replace(/&lt;\/(b|strong|i|em|a)&gt;/g, (match, tag) => {
    if (tag === 'b' || tag === 'strong') return '</b>';
    if (tag === 'i' || tag === 'em') return '</i>';
    if (tag === 'a') return '</a>';
    return match;
  });

  // Convert newlines to <br>
  html = html.replace(/\n/g, '<br>');

  return html;
}

function escapeHtml(text: string): string {
  const map: { [key: string]: string } = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  };
  return text.replace(/[&<>"']/g, char => map[char]);
}

function selectNote(id: number) {
  selectedNoteId = id;
  updateFragment();
  renderFeed();
}

function handleSearch(query: string) {
  searchQuery = query;
  selectedNoteId = null;
  updateFragment();
  renderFeed();
  updateResultsLine();
}

function updateResultsLine() {
  const resultsLine = document.getElementById('results-line')!;
  if (searchQuery) {
    resultsLine.textContent = `results for "${searchQuery}"`;
  } else {
    resultsLine.textContent = '';
  }
}

function handleAddNote(e: Event) {
  e.preventDefault();
  const form = e.target as HTMLFormElement;

  const titleInput = document.getElementById('title') as HTMLInputElement;
  const bodyInput = document.getElementById('body') as HTMLTextAreaElement;
  const avatarInput = document.getElementById('avatar') as HTMLInputElement;

  const title = titleInput.value.trim();
  const body = bodyInput.value.trim();
  const avatar = avatarInput.value.trim();

  if (!title || !body) return;

  // Validate avatar URL
  if (avatar && !isValidAvatarUrl(avatar)) {
    return;
  }

  const newNote: Note = {
    id: nextId++,
    title,
    body,
    avatar,
    createdAt: new Date().toISOString(),
  };

  notes.push(newNote);
  saveNotes();

  form.reset();
  renderFeed();
  updateResultsLine();
}

async function init() {
  await initializeNotes();
  parseFragment();

  // Set up event listeners
  const form = document.getElementById('note-form') as HTMLFormElement;
  form.addEventListener('submit', handleAddNote);

  const searchInput = document.getElementById('search') as HTMLInputElement;
  searchInput.value = searchQuery;
  searchInput.addEventListener('input', (e) => {
    handleSearch((e.target as HTMLInputElement).value);
  });

  // Handle back/forward
  window.addEventListener('hashchange', () => {
    parseFragment();
    renderFeed();
    updateResultsLine();
    const searchInput = document.getElementById('search') as HTMLInputElement;
    searchInput.value = searchQuery;
  });

  // Initial render
  renderFeed();
  updateResultsLine();
}

init().catch(console.error);

